/* GENERATED by gen_hcon_vault.py -- models are generated.
   SAT_FIN_RECEIPT
   anchor      : HUB_FINANCIAL_TRANSACTION   (kind: hub, origin: map.anchor)
   track       : ratified
   history     : SCD2
   feeders     : 1 emitted of 10 (one per source view AND run)
   runs        : 1 -- opus_health_legacy_v4
   payload     : 10 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_FINANCIAL_TRANSACTION_HK
   hashdiff    : SAT_FIN_RECEIPT_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   INTRA-RUN FAN-IN, 3 attribute/run pair(s) with more than one writer, of
   which 3 are genuinely ARBITRARY. WITHIN one run several source views
   write the same attribute and the map declares NO precedence among them,
   so max() picks arbitrarily -- BUT ONLY AMONG UNDISCRIMINATED WRITERS. A
   writer carrying a resolved `instance` or a declared `redundant_of` is
   SEPARATED, not competing: a nominee's name and a policyholder's name on
   one satellite are DIFFERENT ROWS. BOTH SCOPES are quoted below because a
   bare writer count overstates the arbitrariness -- on PARTY_FULL_NAME it
   overstates it nearly fivefold.
   DECLARED, NOT RESOLVED: choosing among same-run writers would invent an
   authority the map does not provide. NO CROSS-RUN DECISION REACHES THIS.
     AMOUNT_RECEIVED                        opus_health_legacy_v4  2 writer(s), of which 2 UNDISCRIMINATED (0 separated by a resolved instance, 0 by redundant_of)  [CROSS-TABLE: check_collapse groups on (table, satellite, attribute, instance, child_key) and CANNOT see this]
     BANK_REFERENCE                         opus_health_legacy_v4  2 writer(s), of which 2 UNDISCRIMINATED (0 separated by a resolved instance, 0 by redundant_of)  [CROSS-TABLE: check_collapse groups on (table, satellite, attribute, instance, child_key) and CANNOT see this]
     RECEIPT_NUMBER                         opus_health_legacy_v4  8 writer(s), of which 8 UNDISCRIMINATED (0 separated by a resolved instance, 0 by redundant_of)  [CROSS-TABLE: check_collapse groups on (table, satellite, attribute, instance, child_key) and CANNOT see this]
   A load-time assertion in models/assertions/ counts the DISTINCT
   values the undiscriminated writers actually supply per key. Until it
   runs, whether they ever disagree is UNKNOWN, not zero.
*/

with feeders as (
    select
        md5(upper('HUB_FINANCIAL_TRANSACTION|' || (HUB_FINANCIAL_TRANSACTION_BK__PTRANSACTION_ID))) as HUB_FINANCIAL_TRANSACTION_HK
        , cast(null as varchar) as AMOUNT_RECEIVED
        , RECEIPT_NO as RECEIPT_NUMBER
        , ADVICE_NO as BANK_REFERENCE
        , CHEQUE_TYPE as CHEQUE_TYPE
        , cast(null as varchar) as PAYMENT_GATEWAY_REFERENCE
        , cast(null as varchar) as RECEIPT_DATE
        , cast(null as varchar) as REALISATION_STATUS
        , cast(null as varchar) as AUTHORISATION_CODE
        , cast(null as varchar) as MERCHANT_REFERENCE
        , cast(null as varchar) as CONVENIENCE_FEE
        , 'BJAZ_HEALTH_WEBSERVICE_INFO' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_health_webservice_info') }}
    where (nullif(trim(PTRANSACTION_ID),'')) is not null
),

resolved as (
    select
        HUB_FINANCIAL_TRANSACTION_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AMOUNT_RECEIVED end) as AMOUNT_RECEIVED,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then RECEIPT_NUMBER end) as RECEIPT_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BANK_REFERENCE end) as BANK_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CHEQUE_TYPE end) as CHEQUE_TYPE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PAYMENT_GATEWAY_REFERENCE end) as PAYMENT_GATEWAY_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then RECEIPT_DATE end) as RECEIPT_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then REALISATION_STATUS end) as REALISATION_STATUS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AUTHORISATION_CODE end) as AUTHORISATION_CODE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MERCHANT_REFERENCE end) as MERCHANT_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CONVENIENCE_FEE end) as CONVENIENCE_FEE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_FINANCIAL_TRANSACTION_HK
),

hashed as (
    select
        *,
        case when AMOUNT_RECEIVED is not null or RECEIPT_NUMBER is not null or BANK_REFERENCE is not null or CHEQUE_TYPE is not null or PAYMENT_GATEWAY_REFERENCE is not null or RECEIPT_DATE is not null or REALISATION_STATUS is not null or AUTHORISATION_CODE is not null or MERCHANT_REFERENCE is not null or CONVENIENCE_FEE is not null
                     then md5(upper(coalesce(cast(AMOUNT_RECEIVED as varchar), '') || '|' || coalesce(cast(RECEIPT_NUMBER as varchar), '') || '|' || coalesce(cast(BANK_REFERENCE as varchar), '') || '|' || coalesce(cast(CHEQUE_TYPE as varchar), '') || '|' || coalesce(cast(PAYMENT_GATEWAY_REFERENCE as varchar), '') || '|' || coalesce(cast(RECEIPT_DATE as varchar), '') || '|' || coalesce(cast(REALISATION_STATUS as varchar), '') || '|' || coalesce(cast(AUTHORISATION_CODE as varchar), '') || '|' || coalesce(cast(MERCHANT_REFERENCE as varchar), '') || '|' || coalesce(cast(CONVENIENCE_FEE as varchar), '')))
                end as SAT_FIN_RECEIPT_HASHDIFF
    from resolved
)

select * from hashed
where HUB_FINANCIAL_TRANSACTION_HK is not null
  and SAT_FIN_RECEIPT_HASHDIFF is not null
